extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_ok", main != null, "La scena principale deve caricarsi senza errori"):
		return
	await wait_frames(20)
	check("no_errors", errors_text() == "", "L'esecuzione non deve provocare errori a schermo: " + errors_text())
	var active: Array = get_prop(main, "active_items", [])
	check("items_cleared", active.size() == 0, "Tutti gli elementi oltre la soglia devono essere stati rimossi dall'array active_items")

