extends Node2D

const LIMIT_Y: float = 400.0

var active_items: Array[Node2D] = []


func _ready() -> void:
	for i in range(5):
		var item := Node2D.new()
		var script_resource: Script = load("res://item.gd")
		item.set_script(script_resource)
		item.position = Vector2(100.0 * (i + 1), 350.0 + (i * 20.0))
		add_child(item)
		active_items.append(item)


func _process(_delta: float) -> void:
	# ERRORE: il ciclo scorre in avanti e prova a usare nodi senza controllare se esistono
	for i in range(active_items.size()):
		var item: Node2D = active_items[i]
		if item.position.y > LIMIT_Y:
			item.free()

extends Node2D

const LIMIT_Y: float = 400.0

var active_items: Array[Node2D] = []


func _ready() -> void:
	for i in range(5):
		var item := Node2D.new()
		var script_resource: Script = load("res://item.gd")
		item.set_script(script_resource)
		item.position = Vector2(100.0 * (i + 1), 350.0 + (i * 20.0))
		add_child(item)
		active_items.append(item)


func _process(_delta: float) -> void:
	for i in range(active_items.size() - 1, -1, -1):
		var item: Node2D = active_items[i]
		if not is_instance_valid(item):
			active_items.remove_at(i)
			continue
		if item.position.y > LIMIT_Y:
			active_items.remove_at(i)
			item.queue_free()
